WITH valid AS (SELECT id, customer_id, plan, end_date, monthly_fee, status, DATEDIFF(CURRENT_DATE(), start_date) AS days_since_start_date FROM subscriptions WHERE end_date > DATE '2024-04-08') SELECT CASE WHEN days_since_start_date >= 65 THEN 'PREMIUM' ELSE 'STANDARD' END AS days_since_start_date_tier, DATE_TRUNC('QUARTER', end_date) AS quarter_start, COUNT_IF(status = 'CANCELLED') AS cancelled_events, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM valid GROUP BY 1, 2 ORDER BY quarter_start DESC
